'use strict';
/* Domínio de teste neutro: contagem de ações em blocos, sem ciência. */
window.DemoEstrutural=()=>{
 let ctx=null,host=null,count=0,note='';
 function draw(){if(!host)return;host.querySelector('output').textContent='Ações registradas: '+count;host.querySelectorAll('rect').forEach((e,i)=>e.classList.toggle('active',i===count%3));host.querySelector('#demo-module').textContent='Módulo '+(ctx.modules.get(ctx.modules.current)?.title||'Explorar');host.querySelector('#demo-add').disabled=!ctx.activity.allowsResource('action');host.querySelector('#demo-annotation').hidden=!ctx.activity.allowsResource('annotation');host.querySelector('#demo-note').value=note;}
 async function act(){if(!ctx.activity.allowsResource('action')){ctx.notify('Recurso bloqueado nesta atividade.',{type:'warning'});return;}count++;draw();await ctx.activity.touch();SimCore.emit('demo:changed',{count});}
 function controls(el,local){const b=document.createElement('button');b.type='button';b.className='secondary-btn';b.textContent='Registrar uma ação';b.id='demo-tool';b.disabled=!local.activity.allowsResource('action');local.scope.listen(b,'click',act);el.append(b);}
 return {
  manifest:{id:'demo',nome:'Demo Estrutural',nomeCurto:'Demo Estrutural',versao:'0.2.4',titulo:'Espaço demonstrativo',subtitulo:'Uma experiência, vários caminhos',icone:'assets/core-icon.svg',
   tema:{dark:{primary:'#346552',accent:'#a2dec9'},light:{primary:'#286049',accent:'#1c5c45'}},manual:window.DemoManual,
   viewport:{label:'Área de investigação demonstrativa'},recursos:['domain/entry.js','domain/demo/bootstrap.js','domain/demo/manual.js','domain/demo/styles.css'],
   painelDireito:{title:'Informações',render(el,local){const p=document.createElement('p');p.id='demo-context';const update=()=>p.textContent='Ações registradas: '+count;update();local.scope.on('demo:changed',update);el.append(p);const b=document.createElement('button');b.type='button';b.className='secondary-btn';b.textContent='Abrir relatório';local.scope.listen(b,'click',()=>local.screens.navigate('relatorios'));el.append(b);}}
  },
  init(context){ctx=context;ctx.experience.configure({
   home:{title:'Escolha seu caminho.',description:'Explore livremente, acompanhe um roteiro ou realize uma missão. A Demo mostra como os ambientes se conectam.',primary:[
    {id:'laboratorio',title:'Laboratório Livre',description:'Entre no workspace e alterne entre Explorar, Medir e Calcular.',icon:'lab',destination:'laboratorio',order:'01'},
    {id:'aprender',title:'Aprender',description:'Consulte temas e seus caminhos relacionados.',icon:'learn',destination:'aprender',order:'02'},
    {id:'missoes',title:'Missões',description:'Registre evidências, conclua e refaça quando quiser.',icon:'mission',destination:'missoes',order:'03'},
    {id:'roteiros',title:'Roteiros Experimentais',description:'Siga um procedimento com um módulo principal.',icon:'routes',destination:'roteiros',order:'04'},
    {id:'caderno',title:'Caderno',description:'Guarde anotações e retome seus registros.',icon:'notebook',destination:'caderno',order:'05'}
   ],support:[
    {id:'manual',title:'Manual',description:'Encontre orientação para cada etapa.',icon:'manual',destination:'manual',order:'01'},
    {id:'professor',title:'Área do Professor',description:'Prepare instruções, recursos e navegação.',icon:'teacher',destination:'professor',order:'02'}
   ]},
   themes:[
    {id:'percursos',title:'Percursos',subtitle:'Pontos de entrada para experiências relacionadas',description:'Organize uma visita por telas, módulos e atividades sem impor uma ordem única.',icon:'routes',related:{content:[{title:'Como começar',destination:'manual',parameter:'primeiros-passos'}],investigations:[{title:'Investigar no Laboratório',destination:'laboratorio'}],routes:['primeiros-passos'],missions:['registrar-e-concluir']}},
    {id:'registros',title:'Registros',subtitle:'Revisar, anotar e compartilhar',description:'Use o caderno e o relatório para guardar o que foi observado e decidido.',icon:'notebook',related:{content:[{title:'Relatórios',destination:'relatorios'}],investigations:[{title:'Investigar no Laboratório',destination:'laboratorio'}],routes:['primeiros-passos'],missions:['registrar-e-concluir']}}
   ],
   notebook:{id:'caderno',route:'caderno',title:'Caderno',description:'Anote ideias e registros da sua exploração.',icon:'notebook',render(el,local){const label=document.createElement('label');label.className='field';label.textContent='Minhas anotações';const input=document.createElement('textarea');input.id='demo-notebook-note';input.rows=8;input.maxLength=6000;input.value=ctx.storage.get('notebook.demo-note','');label.append(input);el.append(label);local.scope.listen(input,'input',()=>ctx.storage.set('notebook.demo-note',input.value));}},
   navigation:{desktop:[{id:'inicio',label:'Início',icon:'home'},{id:'aprender',label:'Aprender',icon:'learn'},{id:'missoes',label:'Missões',icon:'mission'},{id:'roteiros',label:'Roteiros Experimentais',icon:'routes'},{id:'laboratorio',label:'Laboratório',icon:'lab'},{id:'caderno',label:'Caderno',icon:'notebook'},{id:'manual',label:'Manual',icon:'manual'}],mobile:[{id:'inicio',label:'Início',icon:'home'},{id:'aprender',label:'Aprender',icon:'learn'},{id:'laboratorio',label:'Laboratório',icon:'lab'},{id:'caderno',label:'Caderno',icon:'notebook'}]},
   shell:{startup:{destinations:[{id:'inicio',label:'Início'},{id:'aprender',label:'Aprender'},{id:'laboratorio',label:'Laboratório'}]},resources:[{id:'tour',title:'Iniciar tour',icon:'tour',action:()=>SimCore.emit('tour:requested',{domain:'demo'})}]},
   modules:[{id:'explorar',title:'Explorar',description:'Observe os blocos e registre ações.',icon:'grid',badge:'Primeiro contato',controls},{id:'medir',title:'Medir',description:'Acompanhe a contagem de ações demonstrativas.',icon:'lab',controls},{id:'calcular',title:'Calcular',description:'Organize o registro na tabela do relatório.',icon:'report',controls}],
   resources:[{id:'action',title:'Registro de ações'},{id:'annotation',title:'Área de anotações'}],
   routes:[{id:'primeiros-passos',title:'Um percurso pelo workspace',subtitle:'Roteiro demonstrativo · módulo Explorar',module:'explorar',description:'Conheça os painéis e observe o registro das ações.',objective:'Executar uma ação e documentar o resultado.',procedure:['Abra Módulos no painel esquerdo.','Acione Registrar uma ação.','Consulte Informações e abra o relatório.'],requirements:['Teclado, mouse ou toque.'],help:{tips:['Use Informações para conferir o resultado.'],explanations:'Cada ação altera apenas o registro demonstrativo.',manualTopic:'laboratorio'},navigation:'free',restrictions:{resources:['action','annotation']},initialState:{count:0}}],
   missions:[{id:'registrar-e-concluir',title:'Registrar e explicar',subtitle:'Uma missão sem conteúdo científico',module:'medir',objective:'Produzir um registro acompanhado de uma conclusão.',problem:'Como demonstrar que uma ação foi realizada?',conditions:['Registre pelo menos uma ação.'],evidence:['Descreva o que foi registrado.'],help:{instructions:'Registre uma ação e documente sua evidência e conclusão.',tips:['Confira o contador antes de concluir.'],explanations:'A conclusão depende do registro de ação e dos dois campos preenchidos.',manualTopic:'relatorio'},navigation:'restricted',restrictions:{resources:['action','annotation']},initialState:{count:0},validate({fields}){return count>0&&fields.evidence.trim()&&fields.conclusion.trim()?{ok:true}:{ok:false,message:'Registre uma ação, uma evidência e uma conclusão.'};}}],
   teacher:true,
   about:{description:'Demonstra os contratos operacionais da Base Estrutural 0.2.4. Nenhum conteúdo científico foi incorporado.',model:'Blocos e contagem de ações servem exclusivamente para testar interação, sessão e relatório.',manualTopic:'primeiros-passos',licenses:['Base Estrutural: GNU GPL v3.','dialog-polyfill: licença BSD, preservada em vendor/dialog-polyfill/LICENSE.']},
   references:[{id:'contratos',type:'tecnica',title:'Contratos da Base Estrutural 0.2.4',authors:['Documentação da distribuição'],year:'2026',source:'docs/CONTRATOS.md',notes:'Referência técnica local incluída no projeto.'}],
   report:{collect(){return {sections:[{title:'Registro demonstrativo',text:note||'Dados fornecidos pelo domínio Demo.',table:{caption:'Ações registradas',headers:['Registro','Quantidade'],rows:[['Ações realizadas',count]]}}]};}},
   session:{hasChanges(){return count>0||!!note.trim();},capture(meta){ctx.storage.set('demo-session-'+meta.sessionId,{count,note});},restore(meta){const saved=ctx.storage.get('demo-session-'+meta.sessionId,{count:0});count=Number.isSafeInteger(saved?.count)&&saved.count>=0?saved.count:0;note=typeof saved?.note==='string'?saved.note.slice(0,1000):'';draw();}},
   onStart(spec){note='';count=Number.isSafeInteger(spec.initialState?.count)?spec.initialState.count:0;draw();}
  });},
  mount(){const style=document.createElement('link');style.rel='stylesheet';style.href='domain/demo/styles.css';document.head.append(style);ctx.scope.cleanup(()=>style.remove());host=document.createElement('section');host.className='demo-stage';host.id='demo-view';host.innerHTML='<p class="eyebrow" id="demo-module">Módulo Explorar</p><h1>Um espaço para experimentar.</h1><svg viewBox="0 0 340 150" role="img" aria-label="Três blocos; o destaque muda a cada ação"><rect x="10" y="25" width="90" height="90" rx="12"/><rect x="125" y="25" width="90" height="90" rx="12"/><rect x="240" y="25" width="90" height="90" rx="12"/></svg><output aria-live="polite"></output><button class="primary-btn" type="button" id="demo-add">Registrar uma ação</button><p>Use os painéis para alternar o módulo e consultar informações.</p><label class="field" id="demo-annotation">Anotação livre<textarea id="demo-note" rows="2" maxlength="1000"></textarea></label>';ctx.viewport.host.append(host);ctx.scope.listen(host.querySelector('#demo-add'),'click',act);ctx.scope.listen(host.querySelector('#demo-note'),'input',async e=>{note=e.target.value;await ctx.activity.touch();});ctx.scope.on('module:changed',draw);ctx.scope.on('activity:changed',draw);draw();},
  activate(){draw();},resize(size){if(host)host.dataset.size=Math.round(size.width)+'×'+Math.round(size.height);},async reset(){count=0;note='';draw();await ctx.activity.touch();ctx.notify('Investigação reiniciada.',{type:'info'});},deactivate(){},destroy(){host=null;ctx=null;}
 };
};
